filtered_customers = Customers.WHERE(
    (
        STARTSWITH(LOWER(name), "j") | ENDSWITH(LOWER(name), "ez")
    ) &
    ENDSWITH(LOWER(state), "a")
)
result = Broker.CALCULATE(
    num_matching_customers=COUNT(filtered_customers)
)

num_transactions_recent_customers = Broker.CALCULATE(
    total_transactions_from_recent_joiners=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, 'now') <= 70
        ).transactions_made
    )
)

result = Customers.WHERE(HAS(transactions_made) == 1).CALCULATE(
    _id=_id,
    time_to_first_transaction_days=DATEDIFF(
        "days",
        join_date,
        transactions_made.WHERE(
            RANKING(by=date_time.ASC(), per="Customers", allow_ties=True) == 1
        ).SINGULAR().date_time
    )
)

asp_q1_2023 = Dealership.CALCULATE(
    average_sale_price_q1_2023=AVG(
        Sales.WHERE(
            (YEAR(sale_date) == 2023) &
            (ISIN(MONTH(sale_date), (1, 2, 3)))
        ).sale_price
    )
)

result = Dealership.CALCULATE(
    average_payment_lag_days=ROUND(
        AVG(
            PaymentsReceived.CALCULATE(
                lag_in_days=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).lag_in_days
        ),
        2
    )
)

highest_priced_car_sold_on_inventory_out_day = Sales.WHERE(
    HAS(car.inventory_snapshots.WHERE((snapshot_date == Sales.sale_date) & (is_in_inventory == False))) == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    car_make=car.make,
    car_model=car.model,
    car_sale_price=sale_price
)

tsc_past_7_days = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, DATETIME('now')) < 7))
)

distinct_customer_ids_with_purchases = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id=_id
)

salespersons_with_cash_payments = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == "cash")) == 1
).CALCULATE(salesperson_id=_id)

# Define the start and end dates for the 3-month period
start_period_date = DATETIME('now', '-3 months')
end_period_date = DATETIME('now')

# Find the top 3 salespersons by revenue in the last 3 months
top_sales_reps_by_revenue = Salespersons.WHERE(
    HAS(sales_made.WHERE(
        (sale_date >= start_period_date) & (sale_date <= end_period_date)
    )) == 1  # Ensure the salesperson has sales in the specified period
).CALCULATE(
    rep_first_name=first_name,
    rep_last_name=last_name,
    total_sales_num=COUNT(
        sales_made.WHERE(
            (sale_date >= start_period_date) & (sale_date <= end_period_date)
        )
    ),
    total_revenue_val=SUM(
        sales_made.WHERE(
            (sale_date >= start_period_date) & (sale_date <= end_period_date)
        ).sale_price
    )
).TOP_K(3, by=total_revenue_val.DESC())

result = Drugs.CALCULATE(
    drug_name = drug_name,
    average_ddd = AVG(
        treatments_used_in.WHERE(HAS(end_dt)==1).CALCULATE(
            # Calculate the duration of the treatment in days
            treatment_duration_days = DATEDIFF("days", start_dt, end_dt)
            # tot_drug_amt is an original field of treatments_used_in and remains accessible
        ).WHERE(
            # Ensure the treatment duration is positive to avoid division by zero or invalid DDD
            treatment_duration_days > 0
        ).CALCULATE(
            # Calculate DDD for this specific treatment: total drug amount / duration in days
            ddd_for_this_treatment = tot_drug_amt / treatment_duration_days
        ).ddd_for_this_treatment # Extract the calculated DDD values for averaging
    )
)

gmail_or_yahoo_patients_count = DermTreatment.CALCULATE(
    num_patients_gmail_yahoo=COUNT(
        Patients.WHERE(
            (ENDSWITH(email, "@gmail.com")) | (ENDSWITH(email, "@yahoo.com"))
        )
    )
)

result = DermTreatment.CALCULATE(
    num_patients_diag_drug = COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == 'Psoriasis vulgaris') & (drug.drug_type == 'Biologic')
                )
            ) == 1
        )
    )
)

avg_weight_result = DermTreatment.CALCULATE(
    average_weight_kg_for_drugalin_patients=AVG(
        Drugs.WHERE(drug_name == 'Drugalin').treatments_used_in.patient.weight_kg
    )
)

male_patients_average_weight = DermTreatment.CALCULATE(
    caw_male_patients=AVG(Patients.WHERE(gender == "Male").weight_kg)
)

pic_female_patients = DermTreatment.CALCULATE(
    private_insured_female_patient_count=COUNT(
        Patients.WHERE((gender == "Female") & (ins_type == "Private"))
    )
)

result = Drugs.CALCULATE(
    drug_identifier=drug_id,
    name_of_drug=drug_name,
    num_adverse_events_in_month=SUM(
        treatments_used_in.CALCULATE(
            ae_count_for_treatment=COUNT(
                adverse_events.WHERE(
                    (YEAR(reported_dt) == YEAR(start_dt)) & (MONTH(reported_dt) == MONTH(start_dt))
                )
            )
        ).ae_count_for_treatment
    )
).TOP_K(1, by=num_adverse_events_in_month.DESC())

result = Doctors.WHERE(
    HAS(prescribed_treatments.drug.WHERE(drug_type == "biologic")) == 1
).PARTITION(
    name="distinct_doctor_states", by=(loc_state)
).CALCULATE(
    state_name=loc_state
)

result = DermTreatment.CALCULATE(
    avg_patient_age = ROUND(AVG(Patients.WHERE((gender == "Male") & (ins_type == "private")).CALCULATE(
        age_in_years = DATEDIFF("years", date_of_birth, DATETIME('now'))
    ).age_in_years), 0)
)

result = Merchants.CALCULATE(
    mid=mid,
    name=name,
    num_coupons=COUNT(
        coupons.WHERE(
            (YEAR(coupons.created_at) == YEAR(Merchants.created_at)) &
            (MONTH(coupons.created_at) == MONTH(Merchants.created_at))
        )
    )
).TOP_K(1, by=num_coupons.DESC())

users_with_transaction_notifications = Notifications.WHERE(
    CONTAINS(notification_type, "TRANSACTION")
).PARTITION(
    name="distinct_transaction_notification_users", by=(user_id)
).CALCULATE(
    user_id=user_id
)

avg_session_duration_by_device_type = UserSessions.PARTITION(name="sessions_by_device_type", by=(device_type)).CALCULATE(
    device_type = device_type,
    avg_session_duration_seconds = AVG(
        DATEDIFF("seconds", UserSessions.session_start_ts, UserSessions.session_end_ts)
    )
)

users_no_first_year_notification = Users.WHERE(
    HASNOT(
        notifications.WHERE(created_at <= DATETIME(Users.created_at, '1 year'))
    ) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)
